using Meziantou.Framework.WebPlatform.Css.Cascade;
using Meziantou.Framework.WebPlatform.Css.Fonts;
using Meziantou.Framework.WebPlatform.Css.Layout;
using Meziantou.Framework.WebPlatform.Css.Om;
using Meziantou.Framework.WebPlatform.Dom;
using Meziantou.Framework.WebPlatform.Unicode;

namespace Meziantou.Framework.WebPlatform.Tests.Css.Fonts;

/// <summary>
/// The OpenType shaping (GSUB, GPOS and GDEF) with ShapingTest.ttf, a synthetic font generated by
/// <c>Resources/make-shaping-test-font.py</c> (1000 units per em: at 20px, 50 units are 1px): ligature f_i with a GDEF caret,
/// multiple substitution of d, Turkish locl of x, contextual alternate of c before b, Arabic forms of beh, lam and alef,
/// the lam-alef rlig, the kerning of "ab", the mark-to-base attachment of U+0301 on a, the cursive attachment of beh, the
/// small capital of a (smcp) and the superscript of b (sups).
/// </summary>
public sealed class OpenTypeShapingTests : IDisposable
{
    // The glyph ids of the font (the glyph order of the script)
    private const ushort A = 2, B = 3, C = 4, CAlt = 5, DPart1 = 7, DPart2 = 8, F = 9, I = 10, FI = 11, X = 12, XLocl = 13, Acute = 14;
    private const ushort Beh = 17, BehInit = 18, BehMedi = 19, BehFina = 20, LamAlef = 23;
    private const ushort CapitalA = 24, ASmallCap = 25, BSuperscript = 26;

    private static readonly byte[] FontData = File.ReadAllBytes(Path.Combine(TestPaths.Root, "tests", "Meziantou.Framework.WebPlatform.Tests", "Css", "Fonts", "Resources", "ShapingTest.ttf"));

    private readonly BrowsingContextScope _contexts = new();

    public void Dispose() => _contexts.Dispose();

    private Document Load(string body, FontFaceDescriptors? descriptors = null)
    {
        var context = _contexts.Create(new BrowsingContextOptions());
        var document = context.Navigate("https://example.com/", _ => "<style>body { font: 20px Test }</style>" + body);
        var face = new FontFace("Test", FontData, descriptors);
        document.Fonts.Add(face);
        _contexts.EventLoop.RunUntilIdle();
        Assert.Equal(FontFaceLoadStatus.Loaded, face.Status);
        return document;
    }

    private ShapedText Shape(string text, string style = "", string attributes = "", FontFaceDescriptors? descriptors = null, bool singleFont = true)
    {
        var document = Load($"<div id=target {attributes} style=\"{style}\"></div>", descriptors);
        var computed = document.GetStyleEngine().GetStyle(document.QuerySelector("#target")!);
        var shaped = TextShaper.ShapeUncached(text, computed.Fonts, computed.ShapingOptions);
        if (singleFont)
        {
            Assert.All(shaped.Runs.ToArray(), run => Assert.Equal("ShapingTest Regular", run.Font.Font.FullName));
        }

        return shaped;
    }

    private static ushort[] GlyphIds(ShapedText shaped) => [.. shaped.Glyphs.ToArray().Select(glyph => glyph.GlyphId)];

    private double Width(string html)
    {
        var document = Load($"<span id=target>{html}</span>");
        return document.GetElementById("target")!.GetBoundingClientRect().Width;
    }

    [Fact]
    public void Ligature_WithCaret()
    {
        var shaped = Shape("fi");
        Assert.Equal([FI], GlyphIds(shaped));
        Assert.Equal(13, shaped.Width, 9);
        Assert.Equal(0, shaped.Glyphs[0].Cluster);

        // The caret of the GDEF table (300 units) is a caret position inside the ligature
        Assert.True(shaped.IsCaretPosition(1));
        Assert.Equal(6, shaped.GetOffset(1), 9);
        Assert.Equal(1, shaped.GetIndexAtOffset(6.5));
    }

    [Theory]
    [InlineData("font-variant-ligatures: none")]
    [InlineData("font-variant-ligatures: no-common-ligatures")]
    [InlineData("font-feature-settings: 'liga' 0")]
    [InlineData("letter-spacing: 1px")]
    [InlineData("text-rendering: optimizeSpeed")]
    public void Ligature_Disabled(string style)
    {
        Assert.Equal([F, I], GlyphIds(Shape("fi", style)));
    }

    [Fact]
    public void Ligature_FontFaceFeatureSettings()
    {
        // The feature settings of the @font-face rule apply before the ones of the element
        Assert.Equal([F, I], GlyphIds(Shape("fi", descriptors: new FontFaceDescriptors { FeatureSettings = "\"liga\" off" })));
        Assert.Equal([FI], GlyphIds(Shape("fi", "font-feature-settings: 'liga'", descriptors: new FontFaceDescriptors { FeatureSettings = "\"liga\" off" })));
    }

    [Fact]
    public void MultipleSubstitution()
    {
        var shaped = Shape("da");
        Assert.Equal([DPart1, DPart2, A], GlyphIds(shaped));
        Assert.Equal([0, 0, 1], shaped.Glyphs.ToArray().Select(glyph => glyph.Cluster));
        Assert.Equal(22, shaped.Width, 9);
        Assert.Equal(12, shaped.GetOffset(1), 9);
    }

    [Theory]
    [InlineData("", "", X)]
    [InlineData("lang=tr", "", XLocl)]
    [InlineData("lang=tr-TR", "", XLocl)]
    [InlineData("lang=en", "font-language-override: 'TRK'", XLocl)]
    [InlineData("lang=tr", "font-feature-settings: 'locl' 0", X)]
    public void LocalizedForms(string attributes, string style, ushort expected)
    {
        Assert.Equal([expected], GlyphIds(Shape("x", style, attributes)));
    }

    [Fact]
    public void ContextualAlternates()
    {
        Assert.Equal([CAlt, B], GlyphIds(Shape("cb")));
        Assert.Equal([C, A], GlyphIds(Shape("ca")));
        Assert.Equal([C, B], GlyphIds(Shape("cb", "font-variant-ligatures: no-contextual")));
    }

    [Fact]
    public void Kerning_UnsafeToBreak()
    {
        var shaped = Shape("abc");
        Assert.Equal([A, B, C], GlyphIds(shaped));
        Assert.Equal(8, shaped.Glyphs[0].Advance, 9);
        Assert.True(shaped.Glyphs[1].IsUnsafeToBreak);
        Assert.False(shaped.Glyphs[2].IsUnsafeToBreak);
        Assert.True(shaped.IsUnsafeToBreak(1));
        Assert.False(shaped.IsUnsafeToBreak(2));

        Assert.Equal(10, Shape("ab", "font-kerning: none").Glyphs[0].Advance, 9);
    }

    [Fact]
    public void MarkToBase()
    {
        var shaped = Shape("a\u0301");
        Assert.Equal([A, Acute], GlyphIds(shaped));
        Assert.Equal([0, 0], shaped.Glyphs.ToArray().Select(glyph => glyph.Cluster));
        var mark = shaped.Glyphs[1];
        Assert.Equal(0, mark.Advance, 9);

        // The anchor of the base (250, 700) relative to the end of the base
        Assert.Equal(-5, mark.OffsetX, 9);
        Assert.Equal(-14, mark.OffsetY, 9);
        Assert.Equal(10, shaped.Width, 9);
    }

    [Fact]
    public void Arabic_JoiningForms()
    {
        var shaped = Shape("\u0628\u0628\u0628", "direction: rtl");
        Assert.Equal([BehInit, BehMedi, BehFina], GlyphIds(shaped));

        // The cursive attachment of the forms moves the glyphs vertically
        Assert.Contains(shaped.Glyphs.ToArray(), glyph => glyph.OffsetY != 0);

        Assert.Equal([Beh], GlyphIds(Shape("\u0628", "direction: rtl")));
        Assert.Equal([BehInit, Beh], GlyphIds(Shape("\u0628\u200D \u0628", "direction: rtl")).Where(glyph => glyph is BehInit or Beh));
        Assert.Equal([Beh, Beh], GlyphIds(Shape("\u0628\u200C\u0628", "direction: rtl")).Where(glyph => glyph is BehInit or Beh));
    }

    [Fact]
    public void Arabic_RequiredLigature()
    {
        var shaped = Shape("\u0644\u0627", "direction: rtl");
        Assert.Equal([LamAlef], GlyphIds(shaped));
        Assert.Equal(0, shaped.Glyphs[0].Cluster);
    }

    [Fact]
    public void Arabic_Context()
    {
        // The characters around the text (e.g. in another inline box) select the joining forms
        var document = Load("<div id=target style='direction: rtl'></div>");
        var style = document.GetStyleEngine().GetStyle(document.QuerySelector("#target")!);
        var options = style.ShapingOptions with { Context = new ShapingContext(0x0628, 0x0628) };
        Assert.Equal([BehMedi], GlyphIds(TextShaper.ShapeUncached("\u0628", style.Fonts, options)));
        Assert.Equal([BehFina], GlyphIds(TextShaper.ShapeUncached("\u0628", style.Fonts, options with { Context = new ShapingContext(0x0628, 0) })));
    }

    [Fact]
    public void BoundaryShaping_InlineBoxes()
    {
        // https://drafts.csswg.org/css-text-3/#boundary-shaping: the text is shaped across the boundaries of the inline boxes
        // that do not change the font or the shaping options
        Assert.Equal(13, Width("fi"), 3);
        Assert.Equal(13, Width("<span>f</span>i"), 3);
        Assert.Equal(13, Width("<span style='color: red'>f</span><b style='font-weight: normal'>i</b>"), 3);
        Assert.Equal(15, Width("<span style='margin-right: 1px'>f</span>i"), 3);
        Assert.Equal(14, Width("f<span style='font-feature-settings: \"liga\" 0'>i</span>"), 3);
    }

    [Fact]
    public void BoundaryShaping_ArabicJoining()
    {
        // As Chrome, the Arabic letters join across the inline boxes even when the style changes
        var joined = Width("<span dir=rtl>\u0628\u0628\u0628</span>");
        Assert.Equal(joined, Width("<span dir=rtl>\u0628<span style='color: red'>\u0628</span>\u0628</span>"), 3);
        Assert.NotEqual(30, joined, 3);
        Assert.Equal(30, Width("<span dir=rtl>\u0628\u200C\u0628\u200C\u0628</span>"), 3);
    }

    [Theory]
    [InlineData("tr", "TRK ")]
    [InlineData("en-US", "ENG ")]
    [InlineData("zh-Hant-HK", "ZHH ")]
    [InlineData("zh-TW", "ZHT ")]
    [InlineData("sr-Latn", "SRB ")]
    [InlineData("ar", "ARA ")]
    [InlineData("mn-Mong", "MNG ")]
    public void LanguageTags(string language, string expected)
    {
        using var workspace = new ShapingWorkspace();
        Assert.Equal(expected, OpenTypeTag.ToString(workspace.GetLanguages(language, languageOverride: 0)[0]));

        // font-language-override comes first
        Assert.Equal(["SRB ", expected], workspace.GetLanguages(language, OpenTypeTag.FromString("SRB "))[..2].Select(OpenTypeTag.ToString));
    }

    [Fact]
    public void LanguageTags_Unregistered()
    {
        using var workspace = new ShapingWorkspace();
        Assert.Empty(workspace.GetLanguages("xyz", languageOverride: 0));
        Assert.Empty(workspace.GetLanguages(language: null, languageOverride: 0));
    }

    [Fact]
    public void ScriptTags()
    {
        // The scripts of the text, by their ISO 15924 code, have the tags of the OpenType registry
        string[] Tags(UnicodeScript script)
        {
            Span<uint> tags = stackalloc uint[Meziantou.Framework.Fonts.OpenTypeScript.MaxTagCount];
            var count = Meziantou.Framework.Fonts.OpenTypeScript.GetTags(ShapingWorkspace.GetScript(script), tags);
            return [.. tags[..count].ToArray().Select(OpenTypeTag.ToString)];
        }

        Assert.Equal(["dev3", "dev2", "deva"], Tags(UnicodeScript.Devanagari)[..3]);
        Assert.Equal("arab", Tags(UnicodeScript.Arabic)[0]);
        Assert.Equal("kana", Tags(UnicodeScript.KatakanaOrHiragana)[0]);
        Assert.Equal("DFLT", Tags(UnicodeScript.Common)[0]);
    }

    [Fact]
    public void Scripts()
    {
        Assert.Equal(UnicodeScript.Latin, UnicodeProperties.GetScript('a'));
        Assert.Equal(UnicodeScript.Common, UnicodeProperties.GetScript(' '));
        Assert.Equal(UnicodeScript.Arabic, UnicodeProperties.GetScript(0x0628));
        Assert.Equal(UnicodeScript.Inherited, UnicodeProperties.GetScript(0x0301));
        Assert.Equal(UnicodeScript.Mongolian, UnicodeProperties.GetScript(0x1820));

        // The tatweel is used by several joining scripts
        var extensions = UnicodeProperties.GetScriptExtensions(0x0640).ToArray().Select(value => (UnicodeScript)value).ToArray();
        Assert.Contains(UnicodeScript.Arabic, extensions);
        Assert.Contains(UnicodeScript.Syriac, extensions);
        Assert.True(UnicodeProperties.GetScriptExtensions('a').IsEmpty);
    }

    [Fact]
    public void ScriptItemization()
    {
        // A closing bracket takes the script of its opening bracket; the common characters take the script of the run
        var shaped = Shape("a (\u0628) b", "direction: rtl", singleFont: false);
        Assert.Equal(7, shaped.Glyphs.Length);
        Assert.Equal([A, B], GlyphIds(shaped).Where(glyph => glyph is A or B));
    }

    [Fact]
    public void JoiningTypes()
    {
        Assert.Equal(ArabicJoiningType.D, InlineLayoutAlgorithm.GetJoiningType(0x0628));
        Assert.Equal(ArabicJoiningType.R, InlineLayoutAlgorithm.GetJoiningType(0x0627));
        Assert.Equal(ArabicJoiningType.T, InlineLayoutAlgorithm.GetJoiningType(0x064B));
        Assert.Equal(ArabicJoiningType.U, InlineLayoutAlgorithm.GetJoiningType('a'));
        Assert.Equal(ArabicJoiningType.D, InlineLayoutAlgorithm.GetJoiningType(0x1820));
        Assert.Equal(ArabicJoiningType.T, InlineLayoutAlgorithm.GetJoiningType(0x200B));
    }

    [Theory]
    [InlineData("font-variant-caps: small-caps")]
    [InlineData("font-variant-caps: petite-caps")]
    public void SmallCaps_FontFeature(string style)
    {
        // The font has smcp for the Latin script: the small capitals are not synthesized (petite-caps falls back to smcp)
        var shaped = Shape("aA", style);
        Assert.Equal([ASmallCap, CapitalA], GlyphIds(shaped));
        Assert.All(shaped.Runs.ToArray(), run => Assert.Equal(1, run.SynthesisScale));
    }

    [Fact]
    public void AllSmallCaps_SynthesizedWithoutC2sc()
    {
        // The font has no c2sc: as Chrome, all the letters are synthesized (without the smcp feature)
        var shaped = Shape("aA", "font-variant-caps: all-small-caps");
        Assert.Equal([CapitalA, CapitalA], GlyphIds(shaped));
        Assert.All(shaped.Runs.ToArray(), run => Assert.Equal(0.7, run.SynthesisScale, 6));
        Assert.Equal(2 * 600 * 14 / 1000d, shaped.Width, 9);
    }

    [Fact]
    public void SmallCaps_FontFeatureDisabled()
    {
        // https://drafts.csswg.org/css-fonts-4/#font-variant-caps-prop: font-feature-settings: 'smcp' 0 disables the native
        // small capitals of a font that has them, without synthesis
        var shaped = Shape("a", "font-variant-caps: small-caps; font-feature-settings: 'smcp' 0");
        Assert.Equal([A], GlyphIds(shaped));
        Assert.Equal(10, shaped.Width, 9);
    }

    [Fact]
    public void Unicase_LowercasedUppercaseLetters()
    {
        // The font has no unic: the uppercase letters are lowercased and get the small capitals of smcp
        var shaped = Shape("Aa", "font-variant-caps: unicase");
        Assert.Equal([ASmallCap, A], GlyphIds(shaped));
        Assert.Equal(0, shaped.Glyphs[0].Cluster);
        Assert.Equal(1, shaped.Glyphs[1].Cluster);
    }

    [Fact]
    public void Superscript_FontFeature()
    {
        // The font has a superscript for each character of the run: no synthesis
        var shaped = Shape("bb", "font-variant-position: super");
        Assert.Equal([BSuperscript, BSuperscript], GlyphIds(shaped));
        Assert.All(shaped.Glyphs.ToArray(), glyph => Assert.Equal(0, glyph.OffsetY));
        Assert.Equal(1, shaped.Runs[0].SynthesisScale);
    }

    [Fact]
    public void Superscript_SynthesizedRun()
    {
        // https://drafts.csswg.org/css-fonts-4/#font-variant-position-prop: a has no superscript, so the whole run is
        // synthesized from the glyphs without sups (20px: 82% of the size, shifted up by 0.34em)
        var shaped = Shape("ab", "font-variant-position: super");
        Assert.Equal([A, B], GlyphIds(shaped));
        Assert.Equal(0.82, shaped.Runs[0].SynthesisScale, 6);
        Assert.Equal(20 * 0.82, shaped.Runs[0].EmSize, 9);
        Assert.All(shaped.Glyphs.ToArray(), glyph => Assert.Equal(-6.8, glyph.OffsetY, 9));

        // Without the synthesis, the font substitutes what it has
        shaped = Shape("ab", "font-variant-position: super; font-synthesis-position: none");
        Assert.Equal([A, BSuperscript], GlyphIds(shaped));
        Assert.All(shaped.Glyphs.ToArray(), glyph => Assert.Equal(0, glyph.OffsetY));
    }

    [Fact]
    public void WouldSubstitute()
    {
        var font = FontFile.Load(FontData)!.Faces[0];
        Assert.True(font.WouldSubstitute(UnicodeScript.Latin, OpenTypeTag.FromString("sups"), B));
        Assert.False(font.WouldSubstitute(UnicodeScript.Latin, OpenTypeTag.FromString("sups"), A));
        Assert.True(font.WouldSubstitute(UnicodeScript.Latin, OpenTypeTag.FromString("smcp"), A));
        Assert.False(font.WouldSubstitute(UnicodeScript.Latin, OpenTypeTag.FromString("subs"), B));
        Assert.True(font.HasSubstitutionFeature(UnicodeScript.Latin, OpenTypeTag.FromString("smcp")));
        Assert.False(font.HasSubstitutionFeature(UnicodeScript.Latin, OpenTypeTag.FromString("c2sc")));
    }

    [Theory]
    [InlineData("hyphens: auto", "selfish")]
    [InlineData("hyphens: manual", "self&shy;ish")]
    public void Hyphenation_LigatureAcrossTheBreak(string style, string html)
    {
        // The ligature f_i crosses the hyphenation opportunity of "self-ish" (the soft hyphen does not prevent it, as in
        // HarfBuzz): the line broken there ends inside the cluster of the ligature, so the edges of the lines are shaped again,
        // as at the other breaks that are unsafe (as Chrome), and the hyphen is shaped alone
        var document = Load($"<div id=target lang=en style='{style}'>{html}</div>");
        var target = document.GetElementById("target")!;
        var text = Assert.Single(document.GetLayoutEngine().GetTextFragments((Text)target.FirstChild!));
        Assert.Contains(FI, text.Glyphs.ToArray().Select(glyph => glyph.GlyphId));

        target.SetAttribute("style", style + "; width: 0");
        var fragments = document.GetLayoutEngine().GetTextFragments((Text)target.FirstChild!);
        Assert.Equal(3, fragments.Count);
        var (first, hyphen, second) = (fragments[0], fragments[1], fragments[2]);
        Assert.True(hyphen.IsHyphen);
        Assert.Equal(first.GetRectInRoot().Y, hyphen.GetRectInRoot().Y);
        Assert.True(second.GetRectInRoot().Y > first.GetRectInRoot().Y);

        // The first line ends with f (and the invisible glyph of the soft hyphen), the second one starts with i
        var firstGlyphs = first.Glyphs.ToArray().Where(glyph => !glyph.IsInvisible).Select(glyph => glyph.GlyphId).ToArray();
        Assert.Equal(F, firstGlyphs[^1]);
        Assert.Equal(I, second.Glyphs[0].GlyphId);
        Assert.Equal("ish", second.Run.Data[second.Start..second.End]);
        Assert.DoesNotContain(FI, first.Glyphs.ToArray().Select(glyph => glyph.GlyphId));

        // The width of the first line is the one of its characters shaped alone
        var computed = document.GetStyleEngine().GetStyle(target);
        var shaped = TextShaper.ShapeUncached("self", computed.Fonts, computed.ShapingOptions);
        Assert.Equal(shaped.Width, first.Size.Width, 6);
    }
}
